module traffic_light (
    input clk,
    input reset,
    input ped,
    output reg [1:0] light,
    output reg walk
);

    reg [2:0] state;
    reg [2:0] count;

    always @(posedge clk) begin
        if (reset) begin
            state <= 3'd0;
            count <= 3'd0;
            light <= 2'b00;
            walk <= 1'b1;
        end else begin
            if (state == 3'd0) begin // RED
                if (count == 3'd3) begin
                    state <= 3'd1;
                    count <= 3'd0;
                    light <= 2'b01;
                    walk <= 1'b0;
                end else begin
                    count <= count + 1;
                end
            end else if (state == 3'd1) begin // GREEN
                if (count == 3'd4) begin
                    state <= 3'd2;
                    count <= 3'd0;
                    light <= 2'b10;
                    walk <= 1'b0;
                end else begin
                    count <= count + 1;
                end
            end else if (state == 3'd2) begin // YELLOW
                if (count == 3'd2) begin
                    state <= 3'd0;
                    count <= 3'd0;
                    light <= 2'b00;
                    walk <= 1'b1;
                end else begin
                    count <= count + 1;
                end
            end
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            state <= 3'd0;
            count <= 3'd0;
            light <= 2'b00;
            walk <= 1'b1;
        end else begin
            if (state == 3'd1 && ped) begin // GREEN to YELLOW on ped
                state <= 3'd2;
                count <= 3'd0;
                light <= 2'b10;
                walk <= 1'b0;
            end
        end
    end

endmodule

