        walk <= 1'b1;
    end else begin
        if (state == 3'd0) begin
            if (ped) begin
                next_state <= 3'd0;
                cycle_count <= 4'd0;
                light <= 2'b00;
                walk <= 1'b1;
            end else begin
                next_state <= 3'd0;
                cycle_count <= 4'd0;
                light <= 2'b00;
                walk <= 1'b1;
