        end else if (state == 3'd1) begin
            if (cycle_count == 4'd3) begin
                next_state <= 3'd2;
                cycle_count <= 4'd0;
            end else begin
                next_state <= 3'd1;
                cycle_count <= cycle_count + 1;
            end
        end else if (state == 3'd2) begin
            if (cycle_count == 4'd4) begin
                next_state <= 3'd3;
                cycle_count <= 4'd0;
            end else begin
                next_state <= 3'd2;
                cycle_count <= cycle_count + 1;
            end
        end else if (state == 3'd3) begin
            if (cycle_count == 4'd2) begin
                next_state <= 3'd0;
